return-response.set-body:
@{
                var raw = (string)context.Variables["modelList"];
                var data = new JArray();
                foreach (var name in raw.Split(','))
                {
                    var id = name.Trim();
                    if (id.Length == 0) { continue; }
                    var m = new JObject();
                    m["type"] = "model";
                    m["id"] = id;
                    m["display_name"] = id;
                    m["created_at"] = "2026-01-01T00:00:00Z";
                    data.Add(m);
                }
                var body = new JObject();
                body["data"] = data;
                body["has_more"] = false;
                body["first_id"] = data.Count > 0 ? (string)((JObject)data[0])["id"] : null;
                body["last_id"] = data.Count > 0 ? (string)((JObject)data[data.Count - 1])["id"] : null;
                return body.ToString(Newtonsoft.Json.Formatting.None);
            }
